class ForgeSettings:
    def __init__(self, ship_health, alien_health, alien_count):
        self.ship_health = ship_health
        self.alien_health = alien_health
        self.alien_count = alien_count

    def summary(self):
        return f"Ship: {self.ship_health} HP | Aliens: {self.alien_count} x {self.alien_health} HP"
